// The SFX engine — Web Audio buffers, not <audio> tags.
//
// Why: HTMLAudioElement looping has audible seams and pause() stops with a
// click, which is exactly what made the roulette orbit and derby crowd feel
// bad. Decoded AudioBuffers give us gapless loops, envelope fades instead of
// hard cuts, and sample-accurate scheduling (the Wheel schedules one real
// clack per tick on its deceleration curve; craps schedules shake→whoosh→
// tumble→settle against its actual roll window).
//
// Files live in client/public/sfx/ (generated by scripts/gen-sounds.mjs).
// The contract with the game audio libs is graceful degradation: if a file
// is missing or not yet decoded, the caller's synth fallback plays — games
// never go silent. Call preloadSfx() from each game's ensure*Audio() (a user
// gesture) so buffers are warm before the first real play.

import { voice } from "./voice.svelte";
import { sterlingBlips } from "./sterling-voice";

let ctx: AudioContext | null = null;
const buffers = new Map<string, AudioBuffer>();
const loading = new Set<string>();
const failed = new Set<string>();

// ---- App-sounds volume (Settings → Voice & Video → Levels) -----------------
// One master GainNode that EVERY app sound routes through — game SFX files,
// loops, and the custom-scheduled plays (wheel clacks). Per-device like the
// other level sliders. Live: dragging the slider mid-reel-spin is audible.
const VOL_KEY = "solace_sfx_volume";
let sfxVolume = (() => {
  try {
    // (never set = full volume: Number(null) is 0, which silenced every app sound in a fresh browser
    // until the slider was touched — found by the Survivorz stream rig, whose capture came out silent)
    const raw = localStorage.getItem(VOL_KEY);
    if (raw === null) return 1;
    const v = Number(raw);
    return Number.isFinite(v) && v >= 0 && v <= 1.5 ? v : 1;
  } catch {
    return 1;
  }
})();
let master: GainNode | null = null;

export function getSfxVolume(): number {
  return sfxVolume;
}

export function setSfxVolume(v: number): void {
  sfxVolume = Math.max(0, Math.min(1.5, v));
  try {
    localStorage.setItem(VOL_KEY, String(sfxVolume));
  } catch {
    /* private mode */
  }
  if (master) master.gain.value = sfxVolume;
}

/**
 * A GLOBAL playback-rate multiplier on every one-shot and loop this module
 * fires. 1 is off and costs nothing.
 *
 * SLORP (Aug 2026) is the only thing that touches it: on the casino floor a
 * trip pitches the whole room — footsteps, glasses, gunshots, the wheel, the
 * jukebox — because "people sound funny" is not a thing you can sell with one
 * sound effect. It lives here rather than in the casino because this is the
 * single choke point every sound already passes through, and because a value
 * left behind by a crashed game would otherwise pitch the whole app forever:
 * the floor resets it on teardown, and nothing else ever sets it.
 */
let sfxRate = 1;

export function setSfxRate(rate: number): void {
  sfxRate = Math.max(0.35, Math.min(2.2, Number.isFinite(rate) ? rate : 1));
}

export function getSfxRate(): number {
  return sfxRate;
}

/** The node custom scheduling should connect to instead of ctx.destination —
 *  anything wired here obeys the App-sounds volume slider. */
export function sfxOut(): AudioNode | null {
  ensureCtx();
  return master;
}

function ensureCtx(): AudioContext | null {
  if (ctx) {
    if (ctx.state === "suspended") void ctx.resume();
    return ctx;
  }
  try {
    const Ctor =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    ctx = new Ctor();
    master = ctx.createGain();
    master.gain.value = sfxVolume;
    master.connect(ctx.destination);
    return ctx;
  } catch {
    return null;
  }
}

function load(id: string): void {
  if (buffers.has(id) || loading.has(id) || failed.has(id)) return;
  const c = ensureCtx();
  if (!c) return;
  loading.add(id);
  fetch(`/sfx/${id}.ogg`)
    .then((r) => {
      if (!r.ok) throw new Error(String(r.status));
      return r.arrayBuffer();
    })
    .then((ab) => c.decodeAudioData(ab))
    .then((buf) => {
      buffers.set(id, buf);
      loading.delete(id);
    })
    .catch(() => {
      failed.add(id);
      loading.delete(id);
    });
}

/** Warm the cache (call from a game's ensure*Audio — i.e. a user gesture). */
export function preloadSfx(ids: string[]): void {
  for (const id of ids) load(id);
}

// The ENTIRE generated bank (mirrors client/public/sfx/). Preloaded once
// right after login so the FIRST play in every game is the real file — the
// per-game lazy preloads raced the first gesture, and play #1 always fell
// back to the old synth ("the first sound from each game is the old sound").
const ALL_SFX = [
  "card-deal", "card-deal3", "card-flip", "card-muck", "shuffle",
  "chip-place", "chip-few", "chip-push", "chip-cascade",
  "dice-shake", "dice-tumble", "crowd-cheer", "crowd-groan", "crowd-gasp",
  "wheel-clack", "wheel-thud", "wheel-win-common", "wheel-win-rare",
  "wheel-win-legendary", "wheel-talisman", "wheel-womp", "wheel-death",
  "wheel-reaper", "mystery-open",
  "slots-lever", "slots-reelspin", "slots-reelstop", "slots-payout", "slots-jackpot",
  "roulette-orbit", "roulette-drop", "rake-sweep",
  "craps-whoosh", "craps-tumble", "craps-settle",
  "pit-cupslam", "pit-cuplift", "pit-liar", "pit-diecrack", "pit-crown",
  "derby-horn", "derby-crowd", "derby-buzzer",
  "register", "gavel", "forge", "forge-melt", "lottery-win",
  "chess-move", "chess-capture", "bj-blackjack", "bj-bust",
  // THE FLOOR's legendary-win party track (Josh's own pick, ~114s — the
  // casino plays its opening bars with the strobe + confetti)
  "wheel-legendary-party",
  // Sterling's bar (Josh's own recording, mastered into the bank)
  "drink",
  // …and the vial under it (casino/slorp.ts). Warmed with everything else:
  // the burst is the loudest moment the hall has, and it must not be the one
  // sound that arrives as a synth fallback because nobody had played it yet.
  "slorp-drink", "slorp-gurgle", "slorp-burst",
  // …and STAR DUST's detonation (Josh's own recording, fart-with-reverb.mp3
  // mastered into the bank). The huff stays synth-only — see stardust-audio.
  "stardust-pop",
];

/** Fetch + decode the whole bank (~1.5 MB, async, idempotent). The context
 *  may still be suspended pre-gesture — decoding works regardless, and the
 *  first real gesture resumes it with every buffer already warm. */
export function preloadAllSfx(): void {
  preloadSfx(ALL_SFX);
}

/** The decoded buffer, if ready (for custom scheduling — the Wheel's ticks). */
export function sfxBuffer(id: string): AudioBuffer | null {
  load(id);
  return buffers.get(id) ?? null;
}

/** The shared context (for custom scheduling against ctx.currentTime). */
export function sfxContext(): AudioContext | null {
  return ensureCtx();
}

function playBuffer(c: AudioContext, buf: AudioBuffer, gain: number, when = 0, rate = 1): AudioBufferSourceNode {
  const src = c.createBufferSource();
  src.buffer = buf;
  src.playbackRate.value = rate * sfxRate;
  const g = c.createGain();
  g.gain.value = Math.max(0, Math.min(1, gain));
  src.connect(g);
  g.connect(master ?? c.destination);
  src.start(when > 0 ? when : undefined);
  return src;
}

/** One shot. `fallback` runs if the file is missing/failed or not decoded yet
 *  (first play before preload finished) — the synth path keeps games alive. */
export function playSfx(id: string, gain = 0.6, fallback?: () => void): void {
  const c = ensureCtx();
  const buf = c ? buffers.get(id) : null;
  if (!c || !buf) {
    load(id);
    fallback?.();
    return;
  }
  playBuffer(c, buf, gain);
}

/** Schedule a one-shot `delayMs` from now (sample-accurate). */
export function playSfxAt(id: string, delayMs: number, gain = 0.6): void {
  const c = ensureCtx();
  const buf = c ? buffers.get(id) : null;
  if (!c || !buf) {
    load(id);
    return;
  }
  playBuffer(c, buf, gain, c.currentTime + delayMs / 1000);
}

/** A gapless loop for `durationMs`: fades in, fades out BEFORE the deadline
 *  (no clicks, no jarring cut), self-stops. Returns an early-stop function
 *  that also fades. Loop files are pre-crossfaded by the generator, so the
 *  seam is inaudible. */
export function playSfxLoop(
  id: string,
  durationMs: number,
  gain = 0.3,
  fallback?: () => void,
  opts: { fadeInMs?: number; fadeOutMs?: number; rateEnd?: number } = {},
): () => void {
  const c = ensureCtx();
  const buf = c ? buffers.get(id) : null;
  if (!c || !buf) {
    load(id);
    fallback?.();
    return () => {};
  }
  const fadeIn = (opts.fadeInMs ?? 180) / 1000;
  const fadeOut = (opts.fadeOutMs ?? 550) / 1000;
  const dur = Math.max(0.3, durationMs / 1000);
  const t0 = c.currentTime;
  const src = c.createBufferSource();
  src.buffer = buf;
  src.loop = true;
  if (opts.rateEnd && opts.rateEnd !== 1) {
    // A slow drift in playback rate (e.g. the roulette ball losing speed).
    src.playbackRate.setValueAtTime(sfxRate, t0);
    src.playbackRate.linearRampToValueAtTime(opts.rateEnd * sfxRate, t0 + dur);
  } else if (sfxRate !== 1) {
    src.playbackRate.value = sfxRate;
  }
  const g = c.createGain();
  const level = Math.max(0, Math.min(1, gain));
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.linearRampToValueAtTime(level, t0 + fadeIn);
  g.gain.setValueAtTime(level, Math.max(t0 + fadeIn, t0 + dur - fadeOut));
  g.gain.linearRampToValueAtTime(0.0001, t0 + dur);
  src.connect(g);
  g.connect(master ?? c.destination);
  src.start();
  src.stop(t0 + dur + 0.05);
  let stopped = false;
  return () => {
    if (stopped) return;
    stopped = true;
    const now = c.currentTime;
    g.gain.cancelScheduledValues(now);
    g.gain.setValueAtTime(g.gain.value, now);
    g.gain.linearRampToValueAtTime(0.0001, now + 0.25);
    src.stop(now + 0.3);
  };
}

/** Sterling "speaks" — the refined brass-robot blips (sterling-voice.ts;
 *  Josh's call: the original synth voice, more variance, no wobble). Gated
 *  by the listener's soundboard volume slider; 0 = a mute robot. */
export function sterlingSpeak(kind?: string): void {
  const vol = 0.9 * voice.soundboardVolume;
  if (vol <= 0) return;
  // Grim news gets the low register; announcements sit brighter.
  const mood = kind === "death" ? "low" : kind === "lottery" ? "bright" : "auto";
  sterlingBlips(6 + Math.floor(Math.random() * 5), vol, mood);
}
